mapper.select:
SELECT id, rule_version, city_code, vehicle_tier_id, distance_min_meter, distance_max_meter, guide_min_amount_fen, guide_max_amount_fen, own_vehicle_settle_amount_fen, extra_km_amount_fen, allowed_extra_fee_json, rule_status, effective_at, expire_at, created_at, updated_at, version, included_distance_meter FROM transport_pricing_rule WHERE rule_status='active' AND effective_at<=#{now} AND (expire_at IS NULL OR expire_at>#{now})
AND city_code=#{cityCode}
ORDER BY city_code, vehicle_tier_id, distance_min_meter, id
